import * as E from './lab-engine.js';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s=E.fresh(),toastTimer,flowTimer;const by=t=>E.ofType(s,t)[0],has=t=>!!by(t),allOn=ts=>ts.every(t=>by(t)&&E.powered(s,by(t).id)),networkOK=()=>by('laptop')&&E.test(s,by('laptop').id).ok;
const term=(name,label=name)=>`<a href="#" data-term="${name}">${label}</a>`,opt=(v,t,cur)=>`<option value="${esc(v)}" ${String(cur)===String(v)?'selected':''}>${esc(t)}</option>`,select=(id,items,cur)=>`<select id="${id}">${items.map(([v,t])=>opt(v,t,cur)).join('')}</select>`,input=(id,v,type='text')=>`<input id="${id}" type="${type}" value="${esc(v)}">`,check=(id,on,label)=>`<label class="check"><input id="${id}" type="checkbox" ${on?'checked':''}> ${label}</label>`;
const definitions={
 ip:['IP · Internet Protocol','An IP address names an interface on a network. Think of a house number. IPv4 has four number groups, such as 192.168.50.100. Each group is 0–255. A private address works inside a private network; the router usually uses NAT to reach the public Internet.'],
 subnet:['Subnet mask','A mask marks which address bits identify the network. With 255.255.255.0 (/24), 192.168.50.100 and 192.168.50.110 share a subnet. 192.168.60.100 is different. In a usual /24, .0 names the network and .255 is its broadcast address.'],
 gateway:['Default gateway','The nearby router interface used to reach other networks. It must be reachable on the client’s local subnet. A switch is not automatically your gateway. Same-subnet traffic can stay local without crossing the router.'],
 dhcp:['DHCP · Dynamic Host Configuration Protocol','A service that lends a client an IP address, mask, gateway and often DNS settings. Discover → Offer → Request → Acknowledge (DORA). IPv4 DHCP uses UDP 67 at the server and UDP 68 at the client. Without a lease, Windows may choose an APIPA address in 169.254.0.0/16.'],
 dns:['DNS · Domain Name System','The name directory. DNS translates names into records such as IP addresses. Ordinary DNS uses UDP or TCP 53. A correct IP address does not help a browser find a name if the DNS service is unavailable. The router in this lab forwards DNS requests upstream.'],
 router:['Router','A traffic guide between IP networks. It chooses a next hop using its routing table. Home routers often combine routing, NAT, DHCP, firewall and Wi-Fi, but this lab separates the access point so you can see its job. WAN is the provider side; LAN is the local side.'],
 switch:['Ethernet switch','A local traffic sorter. It learns source MAC addresses and forwards frames to the right port when it knows the destination. Unknown destinations and broadcasts are flooded within the VLAN. It does not replace a router between IP subnets.'],
 vlan:['VLAN · Virtual Local Area Network','A separate Layer 2 broadcast group inside a managed switch. Two access ports in VLAN 10 can share frames; a port in VLAN 20 is isolated. This lab uses access ports only. Cross-VLAN communication needs a router and correctly addressed interfaces. VLAN IDs alone do not assign IP addresses.'],
 nat:['NAT · Network Address Translation','Rewrites network addresses. Home routers commonly use port address translation so many private clients share a public address. This simulation models outbound private IPv4 access and its return mapping. NAT is not the same thing as a firewall.'],
 port:['Ports, plugs and listening services','A physical port is a socket for a cable. A TCP/UDP port is a number identifying a software endpoint. HTTPS normally listens on TCP 443; SMB file sharing uses TCP 445. Ping uses ICMP, not TCP or UDP ports. A successful ping does not prove a service is listening.'],
 ethernet:['Ethernet & cable categories','Ethernet is a family of local network standards. Cat 5e supports 1000BASE-T (1 Gb/s) up to about 328 ft per channel. Cat 6A supports 10GBASE-T up to about 328 ft. The slower endpoint or link limits the path. These copper ports are 1 Gb/s; Cat 6A alone does not upgrade them.'],
 sfp:['SFP+ · Small Form-factor Pluggable Plus','A slot for a compatible module or direct-attach cable. Here both SFP+ endpoints use either 10GBASE-SR optical modules with OM3 LC fiber (up to about 984 ft), or a 10-ft-rated passive DAC. Match the transceiver standard, fiber and both ends. SC provider fiber does not fit LC modules.'],
 ont:['ONT · Optical Network Terminal','Ends the provider’s fiber connection and presents Ethernet for the router’s WAN port. It needs electricity. This lab’s SC provider run is limited to 300 ft for the scenario; that is not a universal fiber distance limit.'],
 ap:['AP · Access Point','Bridges wireless clients into a wired LAN. SSID is the network name. WPA2-AES or WPA3 protects access. Match the password. Here a direct switch cable can supply PoE (Power over Ethernet), so a separate AC cord is optional. Real compatibility and PoE budgets must be checked.'],
 wifi:['Wi-Fi standards','802.11n uses 2.4 or 5 GHz; 802.11ac uses 5 GHz; 802.11ax supports 2.4 and 5 GHz, with Wi-Fi 6E extending into 6 GHz. This AP models a 2.4/5 GHz radio and WPA2/WPA3 association. Channel widths, interference and signal strength are not simulated.'],
 raid:['RAID · Redundant Array of Independent Disks','Combines drives into an array. RAID 0 stripes with no fault tolerance (2+ drives). RAID 1 mirrors (2 here). RAID 5 uses distributed single parity (3+). RAID 6 uses double parity (4+). RAID 10 stripes across mirrored pairs (4+, even count). RAID is not a backup: deletion, malware or a disaster can affect the whole array.'],
 parity:['Parity & rebuilding','Parity is calculated recovery information, not a second full copy of each file. RAID 5 survives one failed member; RAID 6 survives two. A rebuild uses surviving data and redundancy to fill a replacement. Another failure beyond tolerance can make the array unavailable. RAID 10 can survive failures in different mirror pairs, but not both disks in one pair.'],
 nas:['NAS · Network Attached Storage','A storage appliance that shares files over a network, often with SMB. Install its drives, configure RAID, give it a valid IP path and enable the file service. Its array can be healthy while the network or service is broken.'],
 esd:['ESD · Electrostatic Discharge','A tiny static spark can damage electronics. Prepare a properly grounded ESD mat and wrist strap for internal component work. Shut down and unplug the system first. Never open power supplies or work on live mains circuits. The simulator does not model electrical repair.'],
 cpu:['CPU, RAM and compatible parts','CPU means Central Processing Unit: it runs instructions. RAM means Random Access Memory: the active workspace. The teaching board is AM4 with DDR4 UDIMM slots and an 8-core CPU. LGA sockets, DDR5 and laptop SODIMMs are deliberately incompatible choices. This is a specific lab board, not a claim that all rack servers use AM4.'],
 pcie:['PCIe · Peripheral Component Interconnect Express','Expansion connections for devices such as network and storage adapters. A NIC is a Network Interface Card. This lab offers a 1 Gb/s copper NIC or a 10 Gb/s SFP+ NIC. Installing an adapter also requires its operating-system driver. Slot generations and lane negotiation are outside this model.'],
 rack:['Rack units & airflow','1U is 1.75 inches high. The lab rack holds 12U. A 2U device needs two adjacent free units. Use compatible rails or a shelf, keep heavy UPS equipment low, and leave air paths open. Front/rear views help you separate mounting from cabling.'],
 ups:['UPS & PDU','UPS means Uninterruptible Power Supply: a short-term battery power source. PDU means Power Distribution Unit: extra rated outlets for a rack. Wall → UPS → PDU → devices. A PDU alone does not provide battery backup. This charged UPS supports a brief simulated outage with a 900 W output budget.'],
 hypervisor:['Hypervisor & virtual machine','A hypervisor shares a physical host’s CPU, RAM and storage among virtual machines (VMs). Each VM needs a guest OS. Type 1 runs directly on hardware; type 2 runs on a host OS. Hardware virtualization must be enabled in firmware. Losing the host can stop all its guests.'],
 vswitch:['Virtual switch modes','External connects guest networking to a physical network through the host adapter. Internal connects the host and its guests. Private connects guests on that host only. In Hyper-V, internal or private alone does not create Internet access; routing/NAT needs separate setup. This lab has no guest NAT service.'],
 cloud:['Cloud deployment & service models','Public: provider services available to many customers. Private: exclusive to one organization, on- or off-site. Community: organizations with shared needs. Hybrid: distinct clouds connected for coordinated use. IaaS supplies virtual infrastructure; you manage the guest OS. PaaS supplies an app platform. SaaS supplies the finished app. A home lab alone is not automatically a private cloud.'],
 backup:['Backup & recovery','A backup is a separate recoverable copy. RAID keeps service available after certain disk failures; it does not protect against all data loss. This lab records a simulated off-site backup and can check that record. No actual user files are uploaded. Test real restores, not just backup completion messages.'],
 ttl:['TTL · Time To Live','An IPv4 packet’s hop limit. Routers reduce it when forwarding. If it reaches zero, the packet is discarded, helping stop routing loops. A Layer 2 switch forwarding a frame does not normally reduce IP TTL. Traceroute tools use expired hop limits to discover hops.']};
function showTerm(name){if(!definitions[name])return;const [title,body]=definitions[name];$('termContent').innerHTML=`<p class="eyebrow">LAB DICTIONARY</p><h2>${title}</h2><p>${body}</p><p>${term('ip','IP addressing')} · ${term('raid','RAID')} · ${term('vswitch','Virtual switches')} · ${term('cloud','Cloud')}</p>`;if(!$('termDialog').open)$('termDialog').showModal();}
function toast(message,ok=true){$('toast').textContent=message;$('toast').className=ok?'visible':'visible error';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').className='',7000);}
function result(r){s.events.unshift(r.message||r.why);s.events=s.events.slice(0,60);s.lastTest=null;render();toast(r.message||r.why,r.ok);return r.ok;}
const guidance=(title,body,help,pass)=>({title,body,help,pass});
const foundation=[
 guidance('1. Meet the equipment','Your laptop needs a local road and a road to the Internet. Add an ONT, router, switch, laptop and PDU from the shelf.','The ONT changes the provider handoff into Ethernet. The router connects networks. The switch adds local ports. The PDU distributes power. Click each item in the shelf once; then select its picture to open the inspector.',()=>['ont','router','switch','laptop','pdu'].every(has)),
 guidance('2. Give the lab power','Connect the wall to the PDU, then give each active device its own power cord. Turn them on.','Select the PDU. Under Ports & cables, join its ac input to Wall out1 with an AC power cord. Then select each ONT, router, switch and laptop: join ac to a different PDU out port. Use 6 ft cords. Switch on the PDU and all four devices. A passive patch panel never needs power.',()=>allOn(['pdu','ont','router','switch','laptop'])),
 guidance('3. Build the data road','Connect provider fiber → ONT → router WAN. Connect router LAN1 → switch P1, then laptop ETH → switch P2.','Use Provider SC fiber between ISP fiber and ONT fiber. Use Cat 5e between ONT lan and router wan; router lan1 and switch p1; laptop eth and switch p2. Keep each run within its stated length. Power and data are separate paths.',()=>{const l=by('laptop'),r=by('router'),o=by('ont');return l&&r&&o&&E.path(s,E.key(l.id,'eth'),E.key(r.id,'lan1'))&&E.path(s,E.key(r.id,'wan'),E.key(o.id,'lan'))&&E.path(s,E.key(o.id,'fiber'),'isp:fiber')}),
 guidance('4. Let DHCP hand out an address','Select the router and enable DHCP. Keep LAN 192.168.50.1, mask 255.255.255.0, pool 100–150, and DNS 192.168.50.1.','Click Apply router settings. Select the laptop: keep DHCP and click Apply network settings. The address, mask, gateway and DNS fields appear in its lease card. DHCP is the address clerk; DNS is the name directory. They do different jobs.',()=>by('laptop')&&E.network(s,by('laptop').id).ok),
 guidance('5. Open a page and follow the reply','In Test the build, choose the laptop, Internet test page, and HTTPS. Send test traffic. Read each step.','Watch the cable path light up. Your client uses DNS, reaches its gateway, crosses NAT at the router, then opens TCP 443 and TLS for HTTPS. Change DNS to 192.168.50.250 and test again to see why a working cable is not enough. Restore DNS after exploring.',()=>networkOK())];
const storageSteps=[
 guidance('Prepare for internal parts','Place a server. Turn on the grounded mat, wrist strap and clear-airflow tools. Leave the server off and unplugged.','Select the server and choose Inside a server. In Install parts, fit the AM4 CPU, DDR4 32 GB RAM, cooler with paste and 1 Gb/s NIC. The board rejects the wrong socket or RAM type. These actions are simulated; never work on live electronics.',()=>{const d=by('server');return d&&d.cpu==='AM4-8'&&d.ram>=16&&d.cooler&&d.nic!=='none'&&s.safety.clearance}),
 guidance('Install four drives, then mount','Fit four 1 TB SATA SSDs while power is disconnected. Add a UPS. Fit rack supports and mount the UPS at U1 and server at U4.','For each drive select “1 TB SATA SSD” and click Install part. The 12U rack checks overlap: the UPS occupies U1–U2 and the server U4–U5. 1U = 1.75 inches. Use the rack view to see placement.',()=>{const d=by('server'),u=by('ups');return d?.disks.length===4&&d.rack!==null&&u?.rack!==null}),
 guidance('Protect power and initialize RAID','Move PDU power from the wall to UPS out1. Connect UPS ac to the wall and server ac to a free PDU outlet. Turn both on. Choose RAID 10 on the server.','Disconnect only the old Wall→PDU cable in Connected cables. Use separate cords: Wall→UPS→PDU→server. RAID 10 pairs disks 1+2 and 3+4, then stripes across those mirrors. Four 1 TB members provide about 2 TB before formatting. The hardware must be ready before array setup.',()=>{const d=by('server');return d?.raid==='10'&&E.raidStatus(d).ok&&E.powered(s,d.id)&&allOn(['ups'])}),
 guidance('Install the host and connect its network','Install the type-1 hypervisor, load drivers and enable CPU virtualization. Cable server ETH to switch P3. Keep DHCP.','Use the server’s Boot & services controls. The server is an eight-core teaching platform. In Test the build, select server → Internet test page → HTTPS. This checks its power, boot, storage, network and WAN path.',()=>{const d=by('server');return d?.os==='Hypervisor'&&d.drivers&&d.virt&&E.test(s,d.id).ok})];
const virtualSteps=[guidance('Create a computer inside the server','Below the bench, create Web-Lab with 4 GB RAM, 2 vCPUs, 40 GB disk and an External virtual switch.','Choose the server as host. Install the guest OS and start the VM. Enable its web service, then test it from the physical laptop. An external switch lets the guest use the physical LAN; internal and private switches do not provide that path in this model.',()=>s.vms.some(v=>E.vmStatus(s,v).network&&v.service)),guidance('Prove isolation and resilience','Switch the VM to Private and test from the laptop. It should fail. Restore External. Then fail one server drive and observe degraded storage.','In the server’s drive list, fail disk 1. RAID 10 still has its mirror. Rebuild it before failing another disk in that pair. The VM depends on the host’s storage. RAID availability is different from an off-site backup. Restore a healthy array and leave the VM running.',()=>s.vms.some(v=>E.vmStatus(s,v).network)&&by('server')&&E.raidStatus(by('server')).failed===0)];
const missions={wired:{name:'Home network → rack server → VMs',steps:[...foundation,...storageSteps,...virtualSteps]},nas:{name:'Rack storage & RAID',steps:[...foundation,guidance('Create network storage','Add a NAS. While off and unplugged, use the ESD tools and install four 1 TB drives. Fit supports and mount it at U7.','Connect NAS ac to the PDU, NAS eth to switch P3, and turn it on. Choose RAID 5 (3 TB usable). Keep DHCP and enable SMB file sharing. Test laptop → NAS → SMB. Unlike a directly attached disk, this file store depends on its network and service.',()=>{const n=by('nas');return n?.raid==='5'&&n.rack!==null&&E.test(s,by('laptop')?.id,n.id,'smb').ok}),guidance('Rebuild a degraded array','Fail one NAS disk. Check that the SMB share remains available. Click Replace & rebuild on that disk.','With four 1 TB drives, RAID 5 stores three drives’ worth of data plus one drive’s worth of distributed parity. It survives one failed member, not two. The teaching rebuild takes a few seconds; a real rebuild can take many hours.',()=>by('nas')&&E.raidStatus(by('nas')).failed===0&&s.events.some(x=>x.includes('Rebuild completed')))]},virtual:{name:'Virtualization server',steps:[...foundation,...storageSteps,...virtualSteps]},wifi:{name:'Wireless home office',steps:[...foundation,guidance('Bridge the air to the wire','Add an access point. Cable AP eth to switch P3 and turn the AP on. The PoE switch powers it.','Select the AP: use HomeLab, a passphrase of at least 8 characters, WPA2-AES, 5 GHz and channel 36. Apply. Select the laptop, enable Wi-Fi and enter the identical name and password. Disconnect its Ethernet cable to prove the wireless path.',()=>{const l=by('laptop');return l?.network.wifi&&networkOK()&&!s.links.some(x=>x.type!=='power'&&(x.a===l.id||x.b===l.id))}),guidance('Test the access point’s uplink','Send an Internet HTTPS test from the wireless laptop. Inspect the AP uplink, not an imaginary Internet radio.','The AP bridges Wi-Fi into the switch. The router still provides DHCP, routing and NAT. Disable PoE on the switch and the AP loses power unless it has a separate AC path. Restore PoE before completing.',()=>networkOK())]},routed:{name:'Two subnets, one router',steps:[...foundation,guidance('Separate the second broadcast group','Add a second laptop and power it. Connect it to switch P4. Connect router LAN2 to switch P5 after enabling “Separate LAN2 subnet” on the router.','Before adding the LAN2 cable, set switch P4 and P5 to VLAN 20. Keep P1/P2 in VLAN 1. Set router second interface 192.168.60.1 with mask 255.255.255.0. Enable routing. Each physical router interface reaches a different VLAN; no tagged trunk is modeled.',()=>E.ofType(s,'laptop').length===2&&by('router')?.router.secondary),guidance('Route and return','Keep both laptops on DHCP. The first gets 192.168.50.x; the second gets 192.168.60.x. Ping the second laptop from the first.','The destination gateway must point back through its local router interface. Turn routing off to see the failure, then restore it. Router forwarding reduces TTL; local switching does not.',()=>{const [a,b]=E.ofType(s,'laptop');return a&&b&&!E.sameSubnet(E.network(s,a.id).ip,E.network(s,b.id).ip,'255.255.255.0')&&E.test(s,a.id,b.id,'ping').ok})]},cloud:{name:'Local storage + off-site cloud backup',steps:[...foundation,...storageSteps,guidance('Understand the responsibility split','Choose Hybrid deployment and IaaS in the cloud panel, then provision the learning account.','This represents coordinating an organization-controlled environment with a public cloud service. A private subnet by itself is not a private cloud. IaaS gives virtual infrastructure; you remain responsible for the guest OS and app. Read the model explanation before continuing.',()=>s.cloud.account&&s.cloud.model==='hybrid'&&s.cloud.service==='iaas'),guidance('Send a separate backup','Choose the server and run the simulated off-site backup. Then verify the recorded recovery copy.','The backup action needs healthy or degraded-but-accessible source storage plus a working cloud path. RAID alone cannot undo deletion. This button models copying data off-site; it never sends real files. Use Verify recovery copy to check the saved snapshot record.',()=>s.cloud.backup&&s.cloud.verified)]},trouble:{name:'Troubleshoot a faulty home network',steps:[guidance('Find the first broken layer','This starter has three faults: a damaged Ethernet cable, a disabled DHCP service, and a bad DNS resolver. Use readiness checks and test traffic to find them.','Open Connected cables and repair the damaged laptop cable. Select the router, enable DHCP and apply. Test again. Change router DNS from 192.168.50.250 to 192.168.50.1 and apply. Test laptop → Internet → HTTPS. Troubleshoot one layer at a time.',()=>networkOK())]},free:{name:'Free build',steps:[guidance('Build your own configuration','Use any equipment and any view. Try a wired network, a rack, a NAS, a Wi-Fi office, or a virtualization host.','Start with power and compatible hardware. Then connect the local network and configure addressing. Add WAN access only when needed. The rules stay active even without a checklist. Use the lab manual, linked terms and readiness checks whenever you get stuck.',()=>true)]}};
function renderCoach(){const m=missions[s.mission]||missions.wired;s.step=Math.min(s.step,m.steps.length-1);const g=m.steps[s.step];$('missionTitle').textContent=m.name;$('goalTitle').textContent=g.title;$('goalBody').textContent=g.body;$('goalHelp').textContent=g.help;$('goalCount').textContent=`Step ${s.step+1} of ${m.steps.length}`;$('lessonProgress').style.width=((s.step+1)/m.steps.length*100)+'%';$('goalPrev').disabled=s.step===0;$('goalNext').textContent=s.step===m.steps.length-1?'Check completion ✓':'Check & continue →';}
function positions(){const map={wall:[89,18],isp:[11,18]};const ds=s.devices.filter(d=>!['wall','isp'].includes(d.type));ds.forEach((d,i)=>map[d.id]=[14+(i%4)*24,32+Math.floor(i/4)*25]);if(s.view==='network'){const types=['ont','router','switch','laptop','server','nas','ap','panel','ups','pdu'];ds.forEach((d,i)=>{const ti=types.indexOf(d.type);map[d.id]=[14+(ti%4)*24,33+Math.floor(ti/4)*27+E.ofType(s,d.type).indexOf(d)*10]})}if(s.view==='rack'){ds.forEach((d,i)=>map[d.id]=d.rack!==null?[58,87-(d.rack-1+E.catalog[d.type].u/2)*5.5]:[12+(i%2)*20,24+Math.floor(i/2)*13]);}return map;}
function renderScene(){const scene=$('scene');scene.className='scene '+s.view;const map=positions(),n=s.devices.length-2;const height=s.view==='rack'?Math.max(640,Math.ceil(n/2)*84+150):Math.max(640,Math.ceil(n/4)*160+160);scene.style.height=height+'px';$('wires').setAttribute('viewBox','0 0 1000 '+height);$('sceneCaption').textContent={bench:'WORKBENCH · Select equipment to configure it',rack:'12U RACK · Supports and collisions are checked',rear:'REAR / CABLES · Inspect every physical connection',network:'NETWORK MAP · Test traffic to trace its path',inside:'INSIDE · Power off and unplug before fitting parts'}[s.view];let out='';if(s.view==='rack')out+='<div class="rack-frame">'+Array.from({length:12},(_,i)=>`<div class="rack-row">U${12-i}</div>`).join('')+'</div>';if(s.view==='inside'){const d=E.find(s,s.selected)||by('server');out+=`<div class="inside-board"><h3>${d?.type==='server'?esc(d.name):'Select a server to inspect its motherboard'}</h3>${d?.type==='server'?`<div class="part-slot"><span class="part-art cpu-art"></span>AM4 SOCKET<br>${d.cpu?'8-core CPU installed':'Empty socket'}</div><div class="part-slot"><span class="part-art ram-art"></span>DDR4 MEMORY<br>${d.ram||0} GB</div><div class="part-slot">COOLING<br>${d.cooler?'Cooler + thermal paste':'Not fitted'}</div><div class="part-slot"><span class="part-art nic-art"></span>PCIe NETWORK<br>${esc(d.nic)}</div><div class="part-slot"><span class="part-art disk-art"></span>SATA BAYS<br>${d.disks.length} / 4 installed</div><div class="part-slot">STORAGE<br>${d.raid?'RAID '+d.raid:'No array'}</div>`:''}</div>`;}
for(const d of s.devices){const [x,y]=map[d.id];const c=E.catalog[d.type],fixed=['wall','isp'].includes(d.type),icon=c.icon;out+=`<button class="device ${E.powered(s,d.id)?'live':''} ${s.selected===d.id?'selected':''} ${s.view==='rack'&&d.rack!==null&&!fixed?'racked':''}" data-device="${d.id}" style="left:${x}%;top:${y}%;${s.view==='inside'?'opacity:.3;':''}" aria-label="Inspect ${esc(d.name)}"><span class="device-sprite ${['wall','pdu','panel'].includes(d.type)?'hardware-'+d.type:''}" style="background-position:${icon%3*50}% ${Math.floor(icon/3)*100/3}%">${fixed?d.type==='wall'?'⚡':'ISP':''}</span><span class="device-name">${esc(d.name)}</span><span class="device-state"><i class="dot ${E.powered(s,d.id)?'':'off'}"></i> ${fixed?'fixed':d.rack!==null?'U'+d.rack:E.powered(s,d.id)?'powered':'off'}</span></button>`;}$('equipment').innerHTML=out;const path=s.lastTest?.ok?s.lastTest.path||[]:[];$('wires').innerHTML=s.links.map(l=>{const a=map[l.a],b=map[l.b];if(!a||!b)return '';const flowing=path.includes(E.key(l.a,l.ap))&&path.includes(E.key(l.b,l.bp));return `<path class="wire ${l.type==='power'?'power':''} ${l.broken?'broken':''} ${flowing?'flowing':''}" d="M${a[0]*10},${a[1]*height/100} C${a[0]*10},${(a[1]+12)*height/100} ${b[0]*10},${(b[1]+12)*height/100} ${b[0]*10},${b[1]*height/100}"><title>${esc(E.find(s,l.a)?.name+' '+l.ap+' → '+E.find(s,l.b)?.name+' '+l.bp)}</title></path>`}).join('');$('sceneSummary').textContent=`${n} devices · ${s.links.length} cables · ${s.outage?'WALL POWER OUT':'wall power on'}`;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===s.view));}
const descriptions={router:'Connects the local network to other networks. LAN and WAN have different jobs.',switch:'Connects local wired devices. Its access-port VLANs decide which ports share frames.',ont:'Turns the provider fiber handoff into Ethernet for the router WAN.',laptop:'Your client. Use it to request web pages, ping another machine, and open shared files.',server:'A bare teaching server. Fit compatible parts, configure storage, install an OS and load drivers.',nas:'A four-bay file storage appliance. Add drives and RAID, then enable its file-sharing service.',ap:'Bridges Wi-Fi clients into the wired network. Direct switch PoE can supply its power.',ups:'Battery-backed power for a brief outage. Keep its modeled load within 900 W.',pdu:'Distributes power to eight equipment inputs. It does not provide battery backup.',panel:'Passive, one-to-one patch points: front1 joins back1, and so on. It does not switch frames.',wall:'Two simulated 120 V power outputs. Connect a PDU or UPS for the rest of the lab.',isp:'The Internet service provider’s simulated optical handoff. Connect it to the ONT fiber port.'};
function renderInspector(){const d=E.find(s,s.selected);if(!d){$('deviceTitle').textContent='Start with a device';$('devicePanel').innerHTML='';$('deviceIntro').innerHTML='<p>Add equipment from the shelf, then click its picture.</p>';return;}const c=E.catalog[d.type],fixed=['wall','isp'].includes(d.type);$('deviceTitle').textContent=d.name;$('deviceBadge').textContent=E.powered(s,d.id)?'POWERED':'OFF';$('deviceIntro').innerHTML=`<p>${descriptions[d.type]}</p><p>${term(definitions[d.type]?d.type:'port','Explain this equipment')} · ${term('port','Ports explained')}</p>`;let h='';if(!fixed){h+=`<button id="togglePower" class="primary">${d.on?'Shut down':'Turn on'}</button><p class="small">${esc(E.ready(s,d.id).why)} · ${c.watts} W modeled load</p>`;}h+='<h3>Ports & cables</h3><div class="port-list">'+Object.entries(c.ports).map(([p,t])=>`<span class="port-chip">${p} · ${t} ${s.links.some(l=>(l.a===d.id&&l.ap===p)||(l.b===d.id&&l.bp===p))?'●':'○'}</span>`).join('')+'</div>';h+=`<label>This device’s port${select('fromPort',Object.entries(c.ports).map(([p,t])=>[p,p+' · '+t]),'')}</label><label>Connect to${select('toDevice',s.devices.filter(x=>x.id!==d.id).map(x=>[x.id,x.name]),'')}</label><label>Destination port<select id="toPort"></select></label><label>Cable${select('cableType',Object.entries(E.cableTypes).map(([k,v])=>[k,v.name]),'cat5e')}</label><label>Length · ft${input('cableLength',6,'number')}</label><button id="connectCable">Connect ports</button><p class="small">${term('ethernet','Copper limits')} · ${term('sfp','Fiber & SFP+')}</p>`;
if(c.u){h+=`<h3>Rack placement</h3>${check('rails',d.rails,'Compatible rails / shelf fitted')}<label>Bottom rack unit${input('rackU',d.rack||1,'number')}</label><button id="mountDevice">Mount in rack</button><button id="unmountDevice">Move to bench</button><p>${term('rack','Height, supports & airflow')}</p>`;}
if(['server','nas','switch'].includes(d.type)){let parts=[];if(d.type==='server')parts=[['cpu|AM4-8','8-core AM4 CPU'],['cpu|LGA','LGA CPU · wrong socket'],['ram|32','32 GB DDR4 UDIMM'],['ram|16','16 GB DDR4 UDIMM'],['ram|64','64 GB DDR4 UDIMM'],['ram|DDR5','DDR5 module · incompatible'],['cooler|yes','Cooler + thermal paste'],['nic|1g','PCIe 1 Gb/s copper NIC'],['nic|10g','PCIe 10 Gb/s SFP+ NIC']];if(['server','nas'].includes(d.type))parts.push(['disk|1','1 TB SATA SSD'],['disk|2','2 TB SATA SSD'],['disk|4','4 TB SATA SSD']);if(['server','switch'].includes(d.type))parts.push(['sr|sr','10GBASE-SR optical module'],['sr|none','Remove optical module for DAC']);h+=`<h3>Install parts</h3><p class="small">Power off, unplug AC, prepare ${term('esd','ESD tools')}.</p>${select('partChoice',parts,'')}<button id="fitPart">Install part</button>`;if(d.type==='server')h+=`<p>CPU: ${esc(d.cpu||'empty')} · RAM: ${d.ram} GB · Cooler: ${d.cooler?'fitted':'missing'} · NIC: ${esc(d.nic)}</p><p>${term('cpu','CPU & RAM')} · ${term('pcie','PCIe & NIC')}</p>`;}
if(['server','nas'].includes(d.type)){h+=`<h3>Storage & RAID</h3><p>${d.disks.length}/4 drive bays · ${term('raid','RAID choices')}</p>`+d.disks.map((v,i)=>`<div class="disk-slot ${v.failed?'failed':''}">Disk ${i+1} · ${v.tb} TB · ${v.failed?'FAILED':'healthy'} <button data-drive="${i}">${v.failed?'Replace & rebuild':'Simulate failure'}</button></div>`).join('')+`<label>Array level${select('raidLevel',['0','1','5','6','10'].map(x=>[x,'RAID '+x]),d.raid||'10')}</label><button id="setRaid">Initialize RAID</button><p>${esc(E.raidStatus(d).message)} ${d.raid?E.raidStatus(d).usable+' TB usable before overhead.':''}</p><p class="small">RAID 10 pairs: disks 1+2 and 3+4. ${term('parity','Failure tolerance & rebuild')}</p>`;}
if(d.type==='server'){h+=`<h3>Boot & services</h3><label>Install an OS${select('osChoice',[['Windows Server','Windows Server'],['Linux','Linux server'],['Hypervisor','Type-1 hypervisor']],d.os||'Hypervisor')}</label><button id="installOs">Install selected OS</button><button id="resetOs">Remove installed OS (simulation)</button>${check('drivers',d.drivers,'Storage and NIC drivers loaded')}${check('virt',d.virt,'CPU virtualization enabled in firmware')}<p>Current OS: ${esc(d.os||'none')} · ${term('hypervisor','How VMs work')}</p>`;}
if(['laptop','server','nas'].includes(d.type)){const n=d.network,lease=E.network(s,d.id);h+=`<h3>Network configuration</h3><p>${term('ip','IP')} · ${term('subnet','Mask')} · ${term('gateway','Gateway')} · ${term('dns','DNS')}</p><label>Address mode${select('ipMode',[['dhcp','DHCP automatic'],['static','Static manual']],n.mode)}</label><label>Static IPv4${input('ip',n.ip)}</label><label>Subnet mask${input('mask',n.mask)}</label><label>Default gateway${input('gateway',n.gateway)}</label><label>DNS resolver${input('dns',n.dns)}</label>`;if(d.type==='laptop')h+=`${check('useWifi',n.wifi,'Use Wi-Fi instead of Ethernet')}<label>Wi-Fi SSID${input('clientSsid',n.ssid)}</label><label>Wi-Fi passphrase${input('clientPass',n.password)}</label>`;h+=`<button id="applyNetwork">Apply network settings</button><div class="note">${lease.ok?`Address: ${esc(lease.ip)}<br>Mask: ${esc(lease.mask)}<br>Gateway: ${esc(lease.gateway)}<br>DNS: ${esc(lease.dns)}`:esc(lease.why)}</div>${check('webService',d.services.web,'Web service listening on TCP 443')}${check('fileService',d.services.file,'SMB file service listening on TCP 445')}${check('allowService',d.firewall,'Firewall allows these services')}<p class="small">${term('port','Listening ports vs physical ports')}</p>`;}
if(d.type==='router'){const r=d.router;h+=`<h3>Router configuration</h3><label>LAN1 gateway${input('routerLan',r.lan)}</label><label>Mask${input('routerMask',r.mask)}</label>${check('dhcp',r.dhcp,'DHCP enabled')}<div class="row"><label>Pool first host${input('poolStart',r.start,'number')}</label><label>Last host${input('poolEnd',r.end,'number')}</label></div><label>DNS given to clients${input('routerDns',r.dns)}</label>${check('nat',r.nat,'Outbound NAT enabled')}${check('wan',r.wan,'Provider WAN service enabled')}${check('secondary',r.secondary,'Separate LAN2 subnet (routed interface)')}<label>LAN2 gateway${input('routerSecond',r.second)}</label>${check('routing',r.routing,'Route between both LAN subnets')}<button id="applyRouter">Apply router settings</button><p>${term('dhcp','DHCP')} · ${term('nat','NAT')} · ${term('ttl','TTL')}</p>`;}
if(d.type==='switch'){h+=`<h3>Access-port VLANs</h3><p class="small">Ports in the same VLAN share frames. ${term('vlan','What is a VLAN?')}</p>`+Object.keys(d.ports).filter(p=>p!=='ac').map(p=>`<label>${p} VLAN${input('vlan-'+p,d.ports[p].vlan,'number')}</label>`).join('')+`${check('poe',d.poe,'PoE enabled for direct AP links')}<button id="applySwitch">Apply switch settings</button>`;}
if(d.type==='ap'){h+=`<h3>Wireless settings</h3><label>SSID${input('apSsid',d.ssid)}</label><label>Passphrase${input('apPass',d.password)}</label><label>Security${select('apSecurity',[['WPA2-AES','WPA2-AES'],['WPA3','WPA3-Personal'],['open','Open · not allowed in guided lab']],d.security)}</label><label>Band${select('apBand',[['2.4','2.4 GHz'],['5','5 GHz']],d.band)}</label><label>Channel${input('apChannel',d.channel,'number')}</label><button id="applyAp">Apply Wi-Fi settings</button><p>${term('wifi','Wi-Fi standards')} · ${term('ap','AP & PoE')}</p>`;}
if(!fixed)h+='<hr><button id="removeDevice" class="danger">Remove device & its cables</button>';$('devicePanel').innerHTML=h;bindInspector(d);}
function bind(id,event,fn){const el=$(id);if(el)el.addEventListener(event,fn)}
function bindInspector(d){const changeDest=()=>{const x=E.find(s,$('toDevice').value);$('toPort').innerHTML=x?Object.entries(E.catalog[x.type].ports).map(([p,t])=>opt(p,p+' · '+t,'')).join(''):''};changeDest();bind('toDevice','change',changeDest);bind('connectCable','click',()=>result(E.connect(s,d.id,$('fromPort').value,$('toDevice').value,$('toPort').value,$('cableType').value,Number($('cableLength').value))));bind('togglePower','click',()=>{d.on=!d.on;result({ok:true,message:d.name+(d.on?' switched on. Check its actual power and boot state.':' shut down.')})});bind('rails','change',e=>d.rails=e.target.checked);bind('mountDevice','click',()=>result(E.mount(s,d.id,Number($('rackU').value))));bind('unmountDevice','click',()=>{d.rack=null;result({ok:true,message:'Moved to bench.'})});bind('fitPart','click',()=>{const [p,v]=$('partChoice').value.split('|');result(E.fitPart(s,d.id,p,v))});bind('setRaid','click',()=>result(E.configureRaid(s,d.id,$('raidLevel').value)));bind('installOs','click',()=>{if(!E.powered(s,d.id)||!d.cpu||!d.ram||!d.cooler||!E.raidStatus(d).ok)return toast('Power, compatible CPU, RAM, cooling and a working array are required.',false);d.os=$('osChoice').value;result({ok:true,message:'OS installation completed in the teaching model. Load drivers before testing.'})});bind('resetOs','click',()=>{d.os='';s.vms=s.vms.filter(v=>v.host!==d.id);result({ok:true,message:'Simulated OS and guest definitions removed. You may recreate this array.'})});for(const [id,k]of [['drivers','drivers'],['virt','virt'],['allowService','firewall']])bind(id,'change',e=>{d[k]=e.target.checked;result({ok:true,message:'Setting updated.'})});for(const [id,k]of [['webService','web'],['fileService','file']])bind(id,'change',e=>{d.services[k]=e.target.checked;result({ok:true,message:'Service setting updated. Test it from a client.'})});bind('applyNetwork','click',()=>{Object.assign(d.network,{mode:$('ipMode').value,ip:$('ip').value.trim(),mask:$('mask').value.trim(),gateway:$('gateway').value.trim(),dns:$('dns').value.trim()});if(d.type==='laptop')Object.assign(d.network,{wifi:$('useWifi').checked,ssid:$('clientSsid').value,password:$('clientPass').value});result({ok:true,message:'Network settings saved. '+E.network(s,d.id).why})});bind('applyRouter','click',()=>{const r={lan:$('routerLan').value.trim(),mask:$('routerMask').value.trim(),dhcp:$('dhcp').checked,start:Number($('poolStart').value),end:Number($('poolEnd').value),dns:$('routerDns').value.trim(),nat:$('nat').checked,wan:$('wan').checked,secondary:$('secondary').checked,second:$('routerSecond').value.trim(),routing:$('routing').checked};if(!E.validMask(r.mask)||E.ipNumber(r.lan)===null||E.ipNumber(r.second)===null)return toast('Enter valid IPv4 interfaces and a contiguous mask.',false);if(r.secondary&&E.sameSubnet(r.lan,r.second,r.mask))return toast('Separate routed interfaces must use different subnets.',false);const before=d.router;d.router=r;if(E.loopPresent(s)){d.router=before;return toast('That change would bridge a loop. Remove the extra LAN cable first.',false)}result({ok:true,message:'Router settings applied. Check the client lease and test again.'})});bind('applySwitch','click',()=>{const old=JSON.parse(JSON.stringify(d.ports));for(const p of Object.keys(d.ports).filter(p=>p!=='ac')){const v=Number($('vlan-'+p).value);if(!Number.isInteger(v)||v<1||v>4094)return toast('Use VLAN IDs 1–4094.',false)}for(const p of Object.keys(d.ports).filter(p=>p!=='ac'))d.ports[p].vlan=Number($('vlan-'+p).value);if(E.loopPresent(s)){d.ports=old;return toast('These VLAN settings would create a bridge loop.',false)}d.poe=$('poe').checked;result({ok:true,message:'Switch access groups and PoE updated.'})});bind('applyAp','click',()=>{const band=$('apBand').value,ch=$('apChannel').value;if(!((band==='2.4'&&['1','6','11'].includes(ch))||(band==='5'&&['36','40','44','48'].includes(ch))))return toast('This US lab offers 2.4 GHz channels 1/6/11 or 5 GHz channels 36/40/44/48.',false);if($('apPass').value.length<8)return toast('Use a passphrase of at least 8 characters.',false);Object.assign(d,{ssid:$('apSsid').value,password:$('apPass').value,security:$('apSecurity').value,band,channel:ch});result({ok:true,message:'Wireless settings applied. Clients must match.'})});bind('removeDevice','click',()=>{s.devices=s.devices.filter(x=>x.id!==d.id);s.links=s.links.filter(x=>x.a!==d.id&&x.b!==d.id);s.vms=s.vms.filter(v=>v.host!==d.id);s.selected=null;result({ok:true,message:'Device and attached cables removed.'})});}
function renderCables(){$('cableCount').textContent='('+s.links.length+')';$('cableList').innerHTML=s.links.length?s.links.map(l=>`<div class="cable-row"><span>${esc(E.find(s,l.a)?.name)} <b>${l.ap}</b> ↔ ${esc(E.find(s,l.b)?.name)} <b>${l.bp}</b><small>${E.cableTypes[l.type].name} · ${l.length} ft ${l.broken?'· DAMAGED':''}</small></span><button data-break="${l.id}">${l.broken?'Repair':'Damage cable'}</button><button data-unplug="${l.id}">Disconnect</button></div>`).join(''):'<p>No cables connected yet. Select a device to add one.</p>';$('eventLog').innerHTML=s.events.map(x=>`<li>${esc(x)}</li>`).join('');}
function fillKeep(id,items){const cur=$(id).value;$(id).innerHTML=items.map(([v,t])=>opt(v,t,cur)).join('')}
function renderBottom(){const ds=s.devices.filter(d=>['laptop','server','nas'].includes(d.type));fillKeep('testSource',ds.map(d=>[d.id,d.name]));fillKeep('testTarget',[['internet','Internet test page'],['cloud','Cloud service'],...ds.map(d=>[d.id,d.name])]);fillKeep('vmHost',E.ofType(s,'server').map(d=>[d.id,d.name]));$('vmList').innerHTML=s.vms.map(v=>{const r=E.vmStatus(s,v);return `<article class="vm-card"><h4>${esc(v.name)}</h4><p>${v.ram} GB RAM · ${v.cpu} vCPUs · ${v.disk} GB · ${esc(v.mode)}</p><p>${esc(r.why)}</p><button data-vmos="${v.id}">${v.os?'Guest OS installed':'Install guest OS'}</button><button data-vmrun="${v.id}">${v.running?'Stop':'Start'} VM</button><button data-vmservice="${v.id}">${v.service?'Stop':'Enable'} guest web service</button><label>Virtual switch<select data-vmmode="${v.id}">${['external','internal','private'].map(x=>opt(x,x,v.mode)).join('')}</select></label><button data-vmtest="${v.id}">Test from selected physical client</button><button data-vmdelete="${v.id}">Delete VM</button></article>`}).join('');$('cloudModel').value=s.cloud.model;$('cloudService').value=s.cloud.service;$('cloudMeaning').textContent=s.cloud.account?cloudExplanation(s.cloud.model,s.cloud.service):'Choose models to see who operates each layer. This creates no real cloud account.';$('backupStatus').textContent=s.cloud.backup?`Simulated recovery copy recorded from ${s.cloud.sourceName}. ${s.cloud.verified?'Recovery record verified.':'Verify it before relying on it.'}`:'No off-site recovery copy yet.';if(!$('verifyBackup')){const b=document.createElement('button');b.id='verifyBackup';b.textContent='Verify recovery copy';$('backupStatus').after(b);b.onclick=()=>{if(!s.cloud.backup)return toast('Run a backup first.',false);s.cloud.verified=true;result({ok:true,message:'Recovery record verified. This confirms the teaching snapshot, not a real file restore.'})};}}
function cloudExplanation(m,v){return ({public:'Public: a provider serves many customers.',private:'Private: cloud infrastructure is exclusive to one organization.',hybrid:'Hybrid: distinct private and public cloud environments are connected.',community:'Community: organizations share cloud infrastructure for common needs.'}[m]||'')+' '+({iaas:'IaaS: provider manages physical infrastructure; you manage guest OS and apps.',paas:'PaaS: provider manages the platform; you deploy and manage your app.',saas:'SaaS: provider runs the app; you manage your data and access.'}[v]||'');}
function render(){renderCoach();renderScene();renderInspector();renderCables();renderBottom();$('mission').value=s.mission;$('powerOutage').textContent=s.outage?'Restore wall power':'Simulate wall-power loss';$('safetyTools').innerHTML=check('toolMat',s.safety.mat,'Grounded ESD mat')+check('toolStrap',s.safety.strap,'ESD wrist strap')+check('toolClear',s.safety.clearance,'Airflow and workspace clear')+`<p class="small">${term('esd','Safe component handling')}</p>`;for(const [id,k] of [['toolMat','mat'],['toolStrap','strap'],['toolClear','clearance']])$(id).onchange=e=>{s.safety[k]=e.target.checked};}
function testResult(r){s.lastTest=r;$('testResult').innerHTML=`<h3 class="${r.ok?'success':'error-text'}">${r.ok?'PASS':'CHECK'} · ${esc(r.why)}</h3><ol>${(r.trace||[]).map(t=>`<li>${esc(t.replace(/^\d+\. /,''))}</li>`).join('')}</ol>`;renderScene();clearTimeout(flowTimer);flowTimer=setTimeout(()=>{s.lastTest=null;renderScene()},12000);}
function troubleStarter(){for(const type of ['pdu','ont','router','switch','laptop'])E.addDevice(s,type);const p=by('pdu'),o=by('ont'),r=by('router'),w=by('switch'),l=by('laptop');E.connect(s,'wall','out1',p.id,'ac','power',6);[o,r,w,l].forEach((d,i)=>E.connect(s,p.id,'out'+(i+1),d.id,'ac','power',6));E.connect(s,'isp','fiber',o.id,'fiber','sc',20);E.connect(s,o.id,'lan',r.id,'wan','cat5e',6);E.connect(s,r.id,'lan1',w.id,'p1','cat5e',6);E.connect(s,l.id,'eth',w.id,'p2','cat5e',6);s.links.at(-1).broken=true;s.devices.forEach(d=>d.on=true);r.router.dns='192.168.50.250';s.selected=l.id;}
function start(m){s=E.fresh(m);if(m==='trouble')troubleStarter();$('goalResult').textContent='';$('testResult').innerHTML='<p>Choose endpoints and send a test to see what happens.</p>';render();}
$('inventory').innerHTML=Object.entries(E.catalog).filter(([k])=>!['wall','isp'].includes(k)).map(([k,c])=>`<button data-add="${k}"><span class="shelf-icon ${['pdu','panel'].includes(k)?'hardware-'+k:''}" style="background-position:${c.icon%3*50}% ${Math.floor(c.icon/3)*100/3}%"></span><span>${c.name}</span><small>${c.u?c.u+'U':'bench'} · ${c.watts} W</small></button>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const a=b.dataset;if(a.term){e.preventDefault();showTerm(a.term)}if(a.close)$(a.close).close();if(a.add){const r=E.addDevice(s,a.add);if(r.ok)s.selected=r.id;result(r)}if(a.device){s.selected=a.device;renderScene();renderInspector();if(window.matchMedia?.('(max-width:1250px)')?.matches)document.querySelector('.inspector').scrollIntoView({behavior:'smooth',block:'start'})}if(a.view){s.view=a.view;renderScene()}if(a.unplug){s.links=s.links.filter(l=>l.id!==a.unplug);result({ok:true,message:'Cable disconnected.'})}if(a.break){const l=s.links.find(l=>l.id===a.break);l.broken=!l.broken;result({ok:true,message:l.broken?'Cable fault introduced. Test which services lose their path.':'Cable repaired.'})}if(a.drive!==undefined){const d=E.find(s,s.selected),disk=d.disks[Number(a.drive)];if(!disk.failed){disk.failed=true;result({ok:true,message:'Disk failure simulated. '+E.raidStatus(d).message})}else{if(!E.powered(s,d.id)||!E.raidStatus(d).ok)return toast('Rebuild needs a powered controller and enough surviving redundancy. This array needs recovery or a fresh lab.',false);b.disabled=true;b.textContent='Rebuilding…';toast('Replacing with an equal-capacity member and rebuilding from surviving redundancy…');setTimeout(()=>{if(!E.find(s,d.id)||!E.powered(s,d.id)||!E.raidStatus(d).ok)return result({ok:false,message:'Rebuild stopped: power or surviving array became unavailable.'});disk.failed=false;result({ok:true,message:'Rebuild completed. '+E.raidStatus(d).message})},2500)}}const vid=a.vmos||a.vmrun||a.vmservice||a.vmtest||a.vmdelete;if(vid){const v=s.vms.find(x=>x.id===vid);if(a.vmos){v.os='Linux';result({ok:true,message:'Guest OS installed in the model.'})}if(a.vmrun){if(!v.os)return toast('Install the guest OS first.',false);if(!E.ready(s,v.host).ok)return toast('Host is not ready.',false);v.running=!v.running;result({ok:true,message:v.running?'VM started.':'VM stopped.'})}if(a.vmservice){v.service=!v.service;result({ok:true,message:'Guest web service setting updated.'})}if(a.vmtest)testResult(E.testVM(s,$('testSource').value,v.id));if(a.vmdelete){s.vms=s.vms.filter(x=>x.id!==vid);result({ok:true,message:'VM resources released.'})}}});
document.addEventListener('change',e=>{if(e.target.dataset.vmmode){s.vms.find(v=>v.id===e.target.dataset.vmmode).mode=e.target.value;result({ok:true,message:'Virtual switch changed. Test isolation again.'})}});
$('newLab').onclick=()=>{if(s.devices.length>2){$('resetDialog').dataset.mission=$('mission').value;$('resetDialog').showModal()}else start($('mission').value)};$('resetOpen').onclick=()=>{$('resetDialog').dataset.mission=s.mission;$('resetDialog').showModal()};$('confirmReset').onclick=()=>{const m=$('resetDialog').dataset.mission||s.mission;$('resetDialog').close();start(m)};$('helpOpen').onclick=()=>$('manualDialog').showModal();$('glossaryOpen').onclick=()=>{$('termContent').innerHTML='<h2>Terms & definitions</h2>'+Object.entries(definitions).map(([k,[t]])=>`<p>${term(k,t)}</p>`).join('');$('termDialog').showModal()};$('welcomeStart').onclick=()=>{$('welcomeDialog').close();try{localStorage.setItem('home-lab-welcome','1')}catch{}};
$('goalPrev').onclick=()=>{s.step=Math.max(0,s.step-1);$('goalResult').textContent='';renderCoach()};$('goalNext').onclick=()=>{const steps=missions[s.mission].steps,g=steps[s.step];if(!g.pass()){$('goalResult').textContent='Keep building: this step is not complete yet. Open “Show exact steps & why” and use readiness checks.';return;}if(s.step===steps.length-1){$('goalResult').textContent='Lab complete! Keep experimenting, export this build, or choose another configuration.';return;}s.step++;$('goalResult').textContent='Step checked. You are ready for the next task.';renderCoach()};$('coachVoice').onclick=()=>{if(!('speechSynthesis'in window))return toast('This browser does not offer narration.',false);speechSynthesis.cancel();const g=missions[s.mission].steps[s.step],u=new SpeechSynthesisUtterance(g.title+'. '+g.body+' '+g.help);u.rate=.9;speechSynthesis.speak(u)};$('stopVoice').onclick=()=>window.speechSynthesis?.cancel();$('powerOutage').onclick=()=>{s.outage=!s.outage;result({ok:true,message:s.outage?'Wall power lost. Only correctly connected, powered UPS-backed equipment can continue.':'Wall power restored.'})};$('auditLab').onclick=()=>{$('testResult').innerHTML='<h3>Readiness report</h3>'+E.health(s).map(r=>`<p><b>${esc(r.name)}:</b> ${r.ok?'READY':esc(r.why)}</p>`).join('');};$('runTest').onclick=()=>testResult(E.test(s,$('testSource').value,$('testTarget').value,$('testProtocol').value));$('createVm').onclick=()=>result(E.createVM(s,$('vmHost').value,$('vmName').value,Number($('vmRam').value),Number($('vmCpu').value),Number($('vmDisk').value),$('vmMode').value));$('provisionCloud').onclick=()=>{const m=$('cloudModel').value,v=$('cloudService').value;if(!m||!v)return toast('Choose both a deployment and service model.',false);s.cloud.model=m;s.cloud.service=v;s.cloud.account=true;result({ok:true,message:'Learning account provisioned. '+cloudExplanation(m,v)})};$('cloudBackup').onclick=()=>{const source=E.find(s,$('testSource').value);if(!source||!['server','nas'].includes(source.type))return toast('Select a server or NAS as the test source first.',false);const r=E.test(s,source.id,'cloud');testResult(r);if(!r.ok)return;Object.assign(s.cloud,{backup:true,verified:false,sourceName:source.name,capacity:E.raidStatus(source).usable});renderBottom();toast('Simulated off-site recovery copy completed.')};
function validateSave(x){
 if(!x||x.version!==1||!missions[x.mission]||!Array.isArray(x.devices)||x.devices.length>24||!Array.isArray(x.links)||x.links.length>100||!Array.isArray(x.vms)||x.vms.length>32)throw Error('Unsupported lab file.');
 const clean=E.fresh(x.mission),ids=new Set();clean.devices=[];
 const typed=(v,base)=>{if(typeof base==='number'){if(!Number.isFinite(v)||Math.abs(v)>100000)throw Error('Invalid number.');return v;}if(typeof base==='boolean'){if(typeof v!=='boolean')throw Error('Invalid switch value.');return v;}if(typeof base==='string'){if(typeof v!=='string'||v.length>200)throw Error('Invalid text value.');return v;}return base;};
 for(const d of x.devices){if(!d||!E.catalog[d.type]||typeof d.id!=='string'||!/^[a-z]+\d*$/.test(d.id)||ids.has(d.id))throw Error('Invalid device.');ids.add(d.id);const seed=E.fresh();let base;if(['wall','isp'].includes(d.type)){base=E.find(seed,d.type);if(d.id!==d.type)throw Error('Invalid fixed endpoint.');}else base=E.find(seed,E.addDevice(seed,d.type).id);
 for(const k of Object.keys(base)){if(['network','router','services'].includes(k)){if(!d[k]||typeof d[k]!=='object')throw Error('Missing configuration.');for(const q of Object.keys(base[k]))base[k][q]=typed(d[k][q],base[k][q]);}else if(k==='ports'){for(const p of Object.keys(base.ports)){const v=d.ports?.[p]?.vlan;if(!Number.isInteger(v)||v<1||v>4094)throw Error('Invalid VLAN.');base.ports[p].vlan=v;}}else if(k==='disks'){if(!Array.isArray(d.disks)||d.disks.length>4)throw Error('Invalid disks.');base.disks=d.disks.map(v=>{if(![1,2,4].includes(v.tb)||typeof v.failed!=='boolean')throw Error('Invalid member.');return {tb:v.tb,failed:v.failed}});}else if(k==='rack'){if(d.rack!==null&&(!Number.isInteger(d.rack)||d.rack<1||d.rack+E.catalog[d.type].u-1>12))throw Error('Invalid rack position.');base.rack=d.rack;}else base[k]=typed(d[k],base[k]);}
 if(base.network&&!['dhcp','static'].includes(base.network.mode))throw Error('Invalid IP mode.');if(base.raid&&!['0','1','5','6','10'].includes(base.raid))throw Error('Invalid RAID.');clean.devices.push(base);}
 if(!ids.has('wall')||!ids.has('isp'))throw Error('Missing endpoints.');
 clean.nextId=1000;for(const l of x.links){const r=E.connect(clean,l.a,l.ap,l.b,l.bp,l.type,l.length);if(!r.ok)throw Error('Invalid saved cable: '+r.message);clean.links.at(-1).broken=l.broken===true;}
 for(const v of x.vms){if(!E.find(clean,v.host)||E.find(clean,v.host).type!=='server'||!/^vm\d+$/.test(v.id)||ids.has(v.id)||typeof v.name!=='string'||v.name.length>32||!Number.isInteger(v.ram)||v.ram<1||v.ram>32||![1,2,4].includes(v.cpu)||!Number.isInteger(v.disk)||v.disk<10||v.disk>500||!['external','internal','private'].includes(v.mode)||!['','Linux'].includes(v.os)||typeof v.running!=='boolean'||typeof v.service!=='boolean')throw Error('Invalid VM.');ids.add(v.id);clean.vms.push({id:v.id,host:v.host,name:v.name,ram:v.ram,cpu:v.cpu,disk:v.disk,mode:v.mode,os:v.os,running:v.running,service:v.service});}
 for(const k of Object.keys(clean.safety))clean.safety[k]=x.safety?.[k]===true;clean.outage=x.outage===true;clean.step=Number.isInteger(x.step)&&x.step>=0?Math.min(x.step,missions[x.mission].steps.length-1):0;clean.events=Array.isArray(x.events)?x.events.filter(t=>typeof t==='string').map(t=>t.slice(0,400)).slice(0,60):[];clean.view=['bench','rack','rear','network','inside'].includes(x.view)?x.view:'bench';clean.selected=ids.has(x.selected)?x.selected:null;clean.nextId=Math.max(1000,...[...ids].map(id=>Number(id.replace(/^[a-z]+/,''))||0))+200;const c=x.cloud||{};clean.cloud={model:['public','private','hybrid','community'].includes(c.model)?c.model:'',service:['iaas','paas','saas'].includes(c.service)?c.service:'',account:c.account===true,backup:c.backup===true,verified:c.verified===true,sourceName:typeof c.sourceName==='string'?c.sourceName.slice(0,100):'',capacity:Number.isFinite(c.capacity)?c.capacity:0};return clean;
}
$('saveLab').onclick=()=>{try{localStorage.setItem('home-lab-save-v1',JSON.stringify(s));$('saveStatus').textContent='Saved in this browser. Export a file for a portable copy.';toast('Browser save updated.')}catch{toast('Browser storage is unavailable. Export a lab file instead.',false)}};$('loadLab').onclick=()=>{try{const raw=localStorage.getItem('home-lab-save-v1');if(!raw)throw Error('No browser save yet.');s=validateSave(JSON.parse(raw));render();toast('Browser save loaded.')}catch(e){toast(e.message,false)}};$('exportLab').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.href=url;a.download='home-lab-build.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('importLab').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('Lab file is too large.');s=validateSave(JSON.parse(await f.text()));render();toast('Lab imported.')}catch(e){toast(e.message,false)}finally{e.target.value=''}};
render();try{if(!localStorage.getItem('home-lab-welcome'))$('welcomeDialog').showModal()}catch{$('welcomeDialog').showModal()}
